import{_ as e,o as a,c as s,a2 as i}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"Settings Reference","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/settings/index.md","filePath":"user-guide/settings/index.md","lastUpdated":1785993908000}'),r={name:"user-guide/settings/index.md"};function n(o,t,d,l,h,c){return a(),s("div",null,[...t[0]||(t[0]=[i('<h1 id="settings-reference" tabindex="-1">Settings Reference <a class="header-anchor" href="#settings-reference" aria-label="Permalink to &quot;Settings Reference&quot;">​</a></h1><p>The Settings window resizes and maximizes like any other: drag its edges, use the maximize button in the title bar, or double-click the title bar. Worth doing on the Plugins page in particular, which puts a plugin list and that plugin&#39;s settings side by side and has real use for the width.</p><p>A search box sits in the Settings window&#39;s title bar. It matches fuzzily (the same fzf-style matching the main search window uses, with pinyin alias support), not just plain substrings, across every section — including the per-plugin entries under Plugins and Hotkeys&#39; Plugin Actions tab. Each result shows a breadcrumb (e.g. &quot;Index &gt; Network Drives&quot;) so same-named settings under different tabs stay distinguishable. Selecting a result (click, or Up/Down to highlight and Enter) switches to the right section and tab, scrolls the exact control into view, and briefly flashes a highlight border around it.</p><p>Several sections (General, Hotkeys, Index, History, Quick Panel, Service Status) further split into their own row of sub-tabs at the top of the page. If the tab labels don&#39;t all fit — most often in English, since translated labels usually run longer than their Chinese originals — left/right arrow buttons appear at the ends of the row so the rest stay reachable by scrolling, instead of just being cut off.</p><p>The Settings window has ten sections in its left sidebar:</p><table tabindex="0"><thead><tr><th>Section</th><th>Covers</th></tr></thead><tbody><tr><td><a href="./service-status.html">Service Status</a></td><td>Background service install, and the App/Hook/Service log viewer.</td></tr><tr><td><a href="./index-drives.html">Index</a></td><td>Local drives, network drives, WSL distributions (once detected), folder indexes, and exclusion rules.</td></tr><tr><td><a href="./general.html">General</a></td><td>Startup behavior, updates, language, search bar layout, and preview window size.</td></tr><tr><td><a href="./hotkeys-page.html">Hotkeys</a></td><td>Global hotkeys, per-plugin action hotkeys, and the process blacklist.</td></tr><tr><td><a href="./plugins.html">Plugins</a></td><td>Installed plugins and per-component enable/disable toggles.</td></tr><tr><td><a href="./localsend.html">LocalSend</a></td><td>Cross-device LAN file, folder, and plain text transfer settings (compatible with official LocalSend clients).</td></tr><tr><td><a href="./favorites.html">Favorites</a></td><td>Custom-named shortcuts to folders, files, and URLs.</td></tr><tr><td><a href="./history.html">History</a></td><td>Search history and quick-window keyword history.</td></tr><tr><td><a href="./quick-panel.html">Quick Panel</a></td><td>The floating panel docked over the window in front: its workspaces, their sources, the tabs plugins contribute, and which apps each workspace belongs to.</td></tr><tr><td><a href="./appearance.html">Appearance</a></td><td>Theme picker (with a preview card per theme) and &quot;follow system light/dark&quot; mode. Pinned above About.</td></tr><tr><td><a href="./about.html">About</a></td><td>Version info and update checking.</td></tr></tbody></table><p>Each page below documents every option on that section, in order, with its default value and any valid range.</p>',7)])])}const g=e(r,[["render",n]]);export{p as __pageData,g as default};
